import { Component, forwardRef, input } from '@angular/core';
import { FormsModule, NG_VALUE_ACCESSOR } from '@angular/forms';
import { NzInputNumberModule } from 'ng-zorro-antd/input-number';
import { HrmControl } from '../shared/hrm-control';
import { HrmSize, HrmStatus, toNzStatus } from '../data-entry/hrm-input';

const toNz = (s: HrmSize) => (s === 'sm' ? 'small' : s === 'lg' ? 'large' : 'default');

/** hrm-money — domain wrapper: nhập tiền, format nghìn + đơn vị. CVA number. */
@Component({
  selector: 'hrm-money',
  imports: [FormsModule, NzInputNumberModule],
  template: `
    <nz-input-number
      style="width:100%"
      [ngModel]="value()"
      (ngModelChange)="emit($event)"
      (nzBlur)="markTouched()"
      [nzMin]="min()"
      [nzStep]="step()"
      [nzDisabled]="disabled()"
      [nzSize]="toNz(size())"
      [nzStatus]="toNzStatus(status())"
      [nzPlaceHolder]="placeholder()"
      [nzFormatter]="formatter"
      [nzParser]="parser"></nz-input-number>
  `,
  host: { class: 'hrm-money', '[class.hrm-status-success]': "status() === 'success'" },
  providers: [{ provide: NG_VALUE_ACCESSOR, useExisting: forwardRef(() => HrmMoney), multi: true }],
})
export class HrmMoney extends HrmControl<number> {
  readonly placeholder = input('');
  readonly size = input<HrmSize>('md');
  readonly status = input<HrmStatus>('');
  readonly min = input(0);
  readonly step = input(1000);
  readonly unit = input('₫');
  protected readonly toNz = toNz;
  protected readonly toNzStatus = toNzStatus;

  protected readonly formatter = (v: number): string =>
    v == null || isNaN(v) ? '' : `${v}`.replace(/\B(?=(\d{3})+(?!\d))/g, '.') + ' ' + this.unit();
  protected readonly parser = (v: string): number => Number(v.replace(/[^\d]/g, '')) || 0;
}
